import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"55、【豐】 離下震上","description":"周易口訣義 - 55、【豐】 離下震上","frontmatter":{"title":"55、【豐】 離下震上","description":"周易口訣義 - 55、【豐】 離下震上"},"headers":[],"relativePath":"classics/koujueyi/057.md","filePath":"classics/koujueyi/057.md"}'),r={name:"classics/koujueyi/057.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_55、【豐】-離下震上" tabindex="-1">55、【豐】 離下震上 <a class="header-anchor" href="#_55、【豐】-離下震上" aria-label="Permalink to “55、【豐】 離下震上”">​</a></h1><p>彖曰：豐，大也。明以動，故豐。「王假之」，尚大也。「勿憂，宜日中」，宜照天下也。日中則昃，月盈則食，天地盈虛，與時消息，而況於人乎？況於鬼神乎？</p><p>象曰：雷電皆至，「豐」。君子以折獄致刑。</p><p>初九：遇其配主，雖旬無咎，往有尚。</p><p>象曰：「雖旬無咎」，過旬災也。</p><p>六二：豐其蔀，日中見鬥。往得疑疾。有孚發若，吉。</p><p>象曰：「有孚發若」，信以發志也。</p><p>九三：豐其沛，日中見沬。折其右肱，無咎。</p><p>象曰：「豐其沛」，不可大事也。「折其右肱」，終不可用也。</p><p>九四，豐其蔀，日中見鬥，遇其夷主，吉。</p><p>象曰：「豐其蔀」，位不當也；「日中見鬥」，幽不明也；「遇其夷主」，吉行也。</p><p>六五，來章，有慶譽，吉。</p><p>象曰：六五之吉，有慶也。</p><p>上六，豐其屋，蔀其家，𬮭其戶，闃其無人，三歲不覿，兇。</p><p>象曰：「豐其屋」，天際翔也；「𬮭其戶，闃其無人」，自藏也。</p><p>解讀</p><p>「豐亨」者，豐是弘大之名，饒益為義，財德盛大，故謂之「豐」。財多能濟於眾，德大無所不通，故曰「豐亨」也。「王假之」者，假，至也，王能至於豐大之德，無所不周也。勿憂，宜日中者，勿，無也，德能廣大，無所不通，如日之中，盛明照臨萬國，德備如此，無復憂慮，為天下主，須令微細隱滯者獲通「豐亨勿憂」之德，故「宜日中」也。象曰「雷電皆至，豐」者，雷，天威也；電，光輝也；威光並至，所以豐大也。「君子以折獄致刑」者，折，斷也；致，至也。君子法天而行，故折斷獄訟，須察虛實，至於刑罰，不濫及無辜也。文明以動，不失情理也。</p><p>「初九，遇其配主，雖旬無咎，往有尚」者，以陽應陽，旬為均平也。豐大之世，文明以動，所貴光大，以合時宜。今初九與四俱陽爻，兩體均平，安得有咎？故曰遇其配主，雖旬無咎，能相光大，往有嘉尚也。</p><p>「六二，豐其蔀，日中見鬥，往得疑疾，有孚發若，吉」者，處豐之時，貴於光顯而惡闇昧。今六二以陰之質應五，又陰是重暗之極，故日中盛明，乃見鬥星，故曰「豐其蔀，日中見鬥」也。蔀者，曖光明之物也。往就於四，四又闇昧，不能啟發其明，心生狐疑而不自決。居乎本位，則暗疾未除，往之與來，不免暗疾，故曰「往得疑疾」。然履中居位，處暗不邪，但懷忠信，不為暗疾所累，而能啟發其志，故獲吉矣，故曰「有孚發若，吉」也。</p><p>九三，豐其沛，日中見沫，折其右肱，無咎。沛，幡幔，御蔽光明之物也。「沬」是微暗不明之謂也。九三應在上六，志在乎陰，雖免豐蔀見鬥，愈乎以陰處陰，而猶豐沛見沬，是日中盛明而見微沬矣，故曰：「豐其沛，日中見沬」。處豐大之時，而見物微沬，斯則不可施於大事。其猶人之所用，在於左右之肱，今右肱既折，況復見物微沬，只可自守而已，乃得無咎，故曰：「折其右肱，無咎。」為施明即見昧，施用則折肱矣。</p><p>「九四，豐其蔀，日中見鬥，遇其夷主，吉」者，九四以陽居陰而懷闇昧，如日中見鬥也。夷，平也。應在初九，以陽適陽，二體均平，能相顯發，若遇初九夷主，所以獲吉，故曰：「遇其夷主，吉」也。</p><p>「六五來章，有慶譽，吉」者，以陰之質來居陽位，是暗而求明。既居尊位，能獲章美慶譽，所以吉，是光大彰顯其德矣。</p><p>「上六，豐其屋，蔀其家，𬮭其戶，闃其無人，三歲不覿，兇」者，屋者，藏陰隱之處。上六以陰處外而不居其位，即是幽隱之人，絕跡深藏者。既是藏隱，恐為人所見，故豐厚其屋，而又蔀覆其家。假使𬮭覷其戶，隱翳之深，而闃寂不見其人，故曰：「豐其屋，蔀其家，闃其戶，闃其無人」也。亦是棄其所止，外處深藏，以高其行。然處豐大之時，即是明君之德，光被天下，野無遺賢，固合睹斯明代，居位佐時，共施政事，而反以自隱三年者，豐道已成而猶不見，所以致兇。治道未濟，隱藏猶可；治道既濟，何為？藏身不出，失時尚兇，況復更藏，兇其宜也。</p>',23)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
